package in.orbitai.mobile;
import android.content.Context;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
/** Explicit endpoint-bound credentials; OpenAI-compatible protocol, with native xAI Responses. */
final class Provider {
 static JSONObject config(Context c)throws Exception{return new JSONObject(Store.get(c,"provider","{\"type\":\"xai\",\"base\":\"https://api.x.ai/v1\"}"));}
 static String slot(JSONObject cfg)throws Exception{byte[] h=MessageDigest.getInstance("SHA-256").digest((cfg.getString("type")+"|"+cfg.getString("base")).getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder("providerKey:");for(byte b:h)s.append(String.format("%02x",b));return s.toString();}
 static String key(Context c,JSONObject cfg)throws Exception{String k=Store.get(c,slot(cfg),"");if(k.isEmpty()&&cfg.optString("type").equals("xai")&&cfg.optString("base").equals("https://api.x.ai/v1"))k=Store.get(c,"apiKey","");return k;}
 static boolean ready(Context c)throws Exception{JSONObject cfg=config(c);return cfg.optString("type").equals("ollama")||!key(c,cfg).isEmpty();}
 static void validate(JSONObject cfg)throws Exception{String type=cfg.getString("type"),base=cfg.getString("base");if(!type.matches("xai|compatible|ollama"))throw new IOException("Unsupported provider protocol");URL u=new URL(base);if(u.getUserInfo()!=null||u.getQuery()!=null||u.getRef()!=null||base.endsWith("/"))throw new IOException("Use an API base URL without credentials, query, fragment or trailing slash");if(type.equals("xai")&&!base.equals("https://api.x.ai/v1"))throw new IOException("Use Compatible for custom endpoints");if(!u.getProtocol().equals("https")){if(!type.equals("ollama")||!u.getProtocol().equals("http"))throw new IOException("Use HTTPS for remote providers");for(InetAddress a:InetAddress.getAllByName(u.getHost()))if(!(a.isLoopbackAddress()||a.isSiteLocalAddress()||a.isLinkLocalAddress()))throw new IOException("HTTP Ollama is limited to your device or private network");}}
 static String call(JSONObject cfg,String path,String method,String body,String key,String id)throws Exception{
  validate(cfg);if(!path.equals("/models")&&!path.equals("/chat/completions"))throw new IOException("Unsupported endpoint");HttpURLConnection c=(HttpURLConnection)new URL(cfg.getString("base")+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(15000);c.setReadTimeout(180000);c.setRequestMethod(method);c.setRequestProperty("Content-Type","application/json");if(!key.isEmpty())c.setRequestProperty("Authorization","Bearer "+key);if(id!=null)AgentService.connections.put(id,c);
  try{if(!method.equals("GET")){c.setDoOutput(true);try(OutputStream o=c.getOutputStream()){o.write(body.getBytes(StandardCharsets.UTF_8));}}int status=c.getResponseCode();if(status<200||status>=300)throw new IOException("Provider HTTP "+status+". Check key, credits, model, endpoint and tool support.");try(InputStream in=c.getInputStream()){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>12000000)throw new IOException("Response too large");}return out.toString("UTF-8");}}
  finally{if(id!=null)AgentService.connections.remove(id,c);c.disconnect();}
 }
 static JSONObject request(JSONObject cfg,JSONObject payload,String key,String id)throws Exception{
  if(cfg.optString("type").equals("xai"))return new JSONObject(AgentService.http("/responses","POST",payload.toString(),key,id));
  JSONArray messages=new JSONArray().put(new JSONObject().put("role","system").put("content",payload.getString("instructions")));JSONArray input=payload.getJSONArray("input");
  for(int i=0;i<input.length();i++){JSONObject item=input.getJSONObject(i);String type=item.optString("type");if(type.equals("function_call")){JSONObject last=messages.length()>0?messages.getJSONObject(messages.length()-1):null;if(last==null||!last.optString("role").equals("assistant")){last=new JSONObject().put("role","assistant").put("content",JSONObject.NULL);messages.put(last);}JSONArray toolCalls=last.optJSONArray("tool_calls");if(toolCalls==null){toolCalls=new JSONArray();last.put("tool_calls",toolCalls);}toolCalls.put(new JSONObject().put("id",item.getString("call_id")).put("type","function").put("function",new JSONObject().put("name",item.getString("name")).put("arguments",item.getString("arguments"))));continue;}if(type.equals("function_call_output")){messages.put(new JSONObject().put("role","tool").put("tool_call_id",item.getString("call_id")).put("content",item.getString("output")));continue;}if(!item.has("role"))continue;Object raw=item.opt("content");JSONArray content=new JSONArray();if(raw instanceof JSONArray){JSONArray parts=(JSONArray)raw;for(int j=0;j<parts.length();j++){JSONObject part=parts.getJSONObject(j);String t=part.optString("type");if(t.equals("input_file"))throw new IOException("PDF attachments currently require xAI mode. Extract text first for other providers.");if(t.equals("input_image"))content.put(new JSONObject().put("type","image_url").put("image_url",new JSONObject().put("url",part.getString("image_url"))));else if(part.has("text"))content.put(new JSONObject().put("type","text").put("text",part.getString("text")));}messages.put(new JSONObject().put("role",item.getString("role")).put("content",content));}else messages.put(new JSONObject().put("role",item.getString("role")).put("content",String.valueOf(raw)));}
  JSONArray tools=new JSONArray(),original=payload.getJSONArray("tools");for(int i=0;i<original.length();i++){JSONObject t=original.getJSONObject(i);if(t.optString("type").equals("function"))tools.put(new JSONObject().put("type","function").put("function",new JSONObject().put("name",t.getString("name")).put("description",t.getString("description")).put("parameters",t.getJSONObject("parameters"))));}
  JSONObject body=new JSONObject().put("model",payload.getString("model")).put("messages",messages).put("stream",false).put(cfg.optString("tokenField","max_tokens"),payload.getInt("max_output_tokens"));if(cfg.optBoolean("toolCalling",true))body.put("tools",tools);
  JSONObject response=new JSONObject(call(cfg,"/chat/completions","POST",body.toString(),key,id)),choice=response.getJSONArray("choices").getJSONObject(0),m=choice.getJSONObject("message");JSONArray out=new JSONArray();String text=m.optString("content","");if(!text.isEmpty()&&!text.equals("null"))out.put(new JSONObject().put("type","message").put("role","assistant").put("content",new JSONArray().put(new JSONObject().put("type","output_text").put("text",text))));JSONArray calls=m.optJSONArray("tool_calls");if(calls!=null)for(int i=0;i<calls.length();i++){JSONObject t=calls.getJSONObject(i),f=t.getJSONObject("function");out.put(new JSONObject().put("type","function_call").put("call_id",t.getString("id")).put("name",f.getString("name")).put("arguments",f.getString("arguments")));}
  JSONObject usage=response.optJSONObject("usage");return new JSONObject().put("output",out).put("status",choice.optString("finish_reason").equals("length")?"incomplete":"completed").put("usage",new JSONObject().put("input_tokens",usage==null?0:usage.optLong("prompt_tokens")).put("output_tokens",usage==null?0:usage.optLong("completion_tokens")));
 }
}
